import React from "react";
import ModulItem from "./modulItemComponenet";

class Myinfo extends React.Component {
    constructor(props){
        super(props);
        this.state = {
            user: null,
            user: null,
            base_URL: ""
        };
    }

    componentDidMount() {
        let token = localStorage.getItem("token");

        if (!token) {
            window.location.href = "/login";
            return;
        }

        fetch("http://localhost:8000/api/profile", {
            headers: {
                "Accept": "application/json",
                "Authorization": "Bearer " + token
            }
        })
        .then(res => res.json())
        .then(json => {
            this.setState({
                user: json.user,
                posts: json.posts,
                base_URL: json.base_URL
            });
        })
        .catch(err => console.log("ERR:", err));
    }

    render() {
        const { user, base_URL } = this.state;

        if (!user) return <p>Loading...</p>;

        return (
            <>
            <div className="d-flex flex-column flex-md-row align-items-center justify-content-between gap-4 mb-4">
                <div className="d-flex align-items-center gap-4">

                    <img
                        src={base_URL + user.img}
                        alt={user.name}
                        className="rounded-circle border"
                        style={{width:"120px", height:"120px", objectFit:"cover"}}
                    />

                    <div>
                        <h4 className="fw-bold mb-1">{user.name}</h4>
                        <p className="mb-2">{user.bio ?? "No bio"}</p>

                        <div className="d-flex gap-4 flex-wrap">
                            <div><strong>0</strong> Posts</div>
                            <div>
                                <a href="#" className="text-decoration-none text-color hover-border"
                                    data-bs-toggle="modal" data-bs-target="#followersModal">
                                    <strong>0</strong> Followers
                                </a>
                            </div>
                            <div>
                                <a href="#" className="text-decoration-none text-color hover-border"
                                    data-bs-toggle="modal" data-bs-target="#followingModal">
                                    <strong>0</strong> Following
                                </a>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="d-flex flex-column gap-2">
                    <a href="/profile/edit" className="btn btn-theme active rounded-pill px-3">
                        Edit Profile
                    </a>

                    <a href="/add/post" className="btn btn-theme active rounded-pill px-3">
                        Upload Post
                    </a>
                </div>
            </div>
            </>
        );
    }
}

export default Myinfo;
